/**
 * Get images for a product by slug
 * Falls back to single image if no gallery found
 */
export function getProductImages(slug: string, fallbackImage: string): string[] {
  const gallery = productImageGalleries[slug];
  if (gallery && gallery.length > 0) {
    return gallery;
  }
  return [fallbackImage];
}
